window.products.push({"id":296691,"name":"La Crosse Technology WT-3181PL-INT 18 inch Atomic Outdoor Clock with Temperature & Humidity","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81TmMcloOgL._AC_SL1500_.jpg","description":"Product Description Manual Set Quartz time movement. Analog Temperature (F/C). Analog Hygrometer (%RH). Simple Operation: Insert 1 AA Alkaline Battery. Indoor/Outdoor use. Temperature Range: -10 F to +130 F(-23 C to +50 C). Humidity Range: 1-percent to 99-percent (%RH). From the Manufacturer Factory Restart: 1. Remove the battery from the clock for 15 minutes. 2. Press the Manual Set Tab at least 20 times to clear all memory. 3. Insert fresh Alkaline battery into the clock. 4. The hands will spin to 12:00, 4:00 or 8:00 and wait for the WWVB time signal","images":["https://m.media-amazon.com/images/I/81TmMcloOgL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"La Crosse Technology","source_asin":"B00OGTOUNO","category_path":"Home & Kitchen"},"sku":"BM-296691","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00OGTOUNO","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00OGTOUNO","price_pending":true,"merchant_ready":false});
